    row_fill_value = {}
    for (r_sec, c_sec), v in input_section_values.items():
        if r_sec not in row_fill_value:
            row_fill_value[r_sec] = v

    # Col fill values (take first value from col section with input)
    col_fill_value = {}
    for (r_sec, c_sec), v in input_section_values.items():
        if c_sec not in col_fill_value:
            col_fill_value[c_sec] = v

    # Build output - start with 0s, keeping 8s
    output = [[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 8:
                output[r][c] = 8

    # Fill each cell
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0:
                r_sec, c_sec = get_section(r), get_section(c)

                # History of who filled this cell
