                fill_source = None

                # First: check if this section has a direct input
                if (r_sec, c_sec) in input_section_values:
                    fill_value = input_section_values[(r_sec, c_sec)]
                    fill_source = "section_input"

                # Second: check row fill
                if r_sec in row_fill_value:
                    row_val = row_fill_value[r_sec]
                    if fill_value is None:
                        fill_value = row_val
                        fill_source = "row_fill"
                    elif fill_value != row_val:
